import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';

interface Message {
  id: string;
  text: string;
  sender: 'user' | 'bot';
  timestamp: Date;
}

interface ZohoAnswerBotProps {
  botId?: string;
  apiEndpoint?: string;
  apiKey?: string;
  orgId?: string;
}

// Inline styles for simplicity
const styles = {
  zobotChat: {
    width: '400px',
    height: '600px',
    border: '1px solid #e0e0e0',
    borderRadius: '12px',
    display: 'flex',
    flexDirection: 'column' as const,
    background: 'white',
    boxShadow: '0 4px 12px rgba(0, 0, 0, 0.1)',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
  },
  chatHeader: {
    padding: '16px 20px',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    color: 'white',
    borderRadius: '12px 12px 0 0',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center'
  },
  chatHeaderH3: {
    margin: 0,
    fontSize: '18px',
    fontWeight: 600
  },
  statusIndicator: {
    fontSize: '12px',
    opacity: 0.9,
    padding: '4px 8px',
    background: 'rgba(255, 255, 255, 0.2)',
    borderRadius: '12px'
  },
  messagesContainer: {
    flex: 1,
    overflowY: 'auto' as const,
    padding: '16px',
    background: '#f8f9fa'
  },
  message: {
    marginBottom: '12px',
    display: 'flex',
    flexDirection: 'column' as const
  },
  userMessage: {
    alignItems: 'flex-end' as const
  },
  botMessage: {
    alignItems: 'flex-start' as const
  },
  messageContent: {
    maxWidth: '80%',
    padding: '12px 16px',
    borderRadius: '18px',
    fontSize: '14px',
    lineHeight: 1.4,
    wordWrap: 'break-word' as const
  },
  userMessageContent: {
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    color: 'white',
    borderBottomRightRadius: '4px'
  },
  botMessageContent: {
    background: 'white',
    color: '#333',
    border: '1px solid #e0e0e0',
    borderBottomLeftRadius: '4px'
  },
  messageTimestamp: {
    fontSize: '11px',
    color: '#999',
    marginTop: '4px',
    padding: '0 4px'
  },
  inputContainer: {
    padding: '16px',
    background: 'white',
    borderTop: '1px solid #e0e0e0',
    borderRadius: '0 0 12px 12px',
    display: 'flex',
    gap: '8px'
  },
  textarea: {
    flex: 1,
    border: '1px solid #e0e0e0',
    borderRadius: '20px',
    padding: '12px 16px',
    fontSize: '14px',
    resize: 'none' as const,
    outline: 'none',
    fontFamily: 'inherit',
    minHeight: '20px',
    maxHeight: '100px'
  },
  button: {
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    color: 'white',
    border: 'none',
    borderRadius: '20px',
    padding: '12px 20px',
    fontSize: '14px',
    fontWeight: 600,
    cursor: 'pointer',
    transition: 'all 0.2s ease'
  },
  buttonDisabled: {
    opacity: 0.6,
    cursor: 'not-allowed'
  },
  typingIndicator: {
    display: 'flex',
    gap: '4px',
    padding: '8px 12px'
  },
  typingDot: {
    width: '8px',
    height: '8px',
    borderRadius: '50%',
    background: '#ccc',
    animation: 'typing 1.4s infinite ease-in-out'
  }
};

const ZohoAnswerBot: React.FC<ZohoAnswerBotProps> = ({ 
  botId = 'YOUR_BOT_ID', 
  apiEndpoint = 'https://desk.zoho.com/api/v1/answerbot',
  apiKey = 'YOUR_API_KEY',
  orgId = 'YOUR_ORG_ID'
}) => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      text: 'Namaste! Main aapka Zoho Answer Bot hun. Kya aapko koi help chahiye?',
      sender: 'bot',
      timestamp: new Date()
    }
  ]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const sendMessage = async () => {
    if (!inputMessage.trim()) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      text: inputMessage,
      sender: 'user',
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputMessage('');
    setIsLoading(true);

    try {
      // Zoho Answer Bot API call
      const response = await axios.post(apiEndpoint, {
        query: inputMessage,
        orgId: orgId,
        botId: botId,
        // Additional parameters for Zoho Answer Bot
        channel: 'web',
        language: 'en'
      }, {
        headers: {
          'Authorization': `Zoho-oauthtoken ${apiKey}`,
          'Content-Type': 'application/json',
          'orgId': orgId
        }
      });

      // Extract response from Zoho Answer Bot
      const botResponse = response.data?.response || 
                         response.data?.answer || 
                         response.data?.message || 
                         'Sorry, I couldn\'t process that request.';

      const botMessage: Message = {
        id: (Date.now() + 1).toString(),
        text: botResponse,
        sender: 'bot',
        timestamp: new Date()
      };

      setMessages(prev => [...prev, botMessage]);
    } catch (error) {
      console.error('Error sending message to Zoho Answer Bot:', error);

      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        text: 'Sorry, there was an error processing your request. Please try again.',
        sender: 'bot',
        timestamp: new Date()
      };

      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  return (
    <div style={styles.zobotChat}>
      <div style={styles.chatHeader}>
        <h3 style={styles.chatHeaderH3}>Zoho Answer Bot</h3>
        <div style={styles.statusIndicator}>
          {isLoading ? 'Typing...' : 'Online'}
        </div>
      </div>

      <div style={styles.messagesContainer}>
        {messages.map((message) => (
          <div
            key={message.id}
            style={{
              ...styles.message,
              ...(message.sender === 'user' ? styles.userMessage : styles.botMessage)
            }}
          >
            <div style={{
              ...styles.messageContent,
              ...(message.sender === 'user' ? styles.userMessageContent : styles.botMessageContent)
            }}>
              {message.text}
            </div>
            <div style={styles.messageTimestamp}>
              {message.timestamp.toLocaleTimeString()}
            </div>
          </div>
        ))}
        {isLoading && (
          <div style={{...styles.message, ...styles.botMessage}}>
            <div style={{...styles.messageContent, ...styles.botMessageContent}}>
              <div style={styles.typingIndicator}>
                <span style={{...styles.typingDot, animationDelay: '-0.32s'}}></span>
                <span style={{...styles.typingDot, animationDelay: '-0.16s'}}></span>
                <span style={styles.typingDot}></span>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div style={styles.inputContainer}>
        <textarea
          style={styles.textarea}
          value={inputMessage}
          onChange={(e) => setInputMessage(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder="Apna sawal yahan type karein..."
          disabled={isLoading}
        />
        <button 
          style={{
            ...styles.button,
            ...(isLoading || !inputMessage.trim() ? styles.buttonDisabled : {})
          }}
          onClick={sendMessage} 
          disabled={isLoading || !inputMessage.trim()}
        >
          Send
        </button>
      </div>
    </div>
  );
};

export default ZohoAnswerBot;
